 on('[data-rc-keep]',()=>{if(screen!=='draft'||!a)return false;const id=keepRehearsalScript(book,source,a.work,{canExport:ctx.canExport});if(!id){message(T.refused);return false;}adopt();let saved;try{saved=ctx.save?.();}catch{saved=null;}const r=rehearsalScriptsView(book).items.find(r=>r.readable&&r.id===id);if(!r)return false;const kept=slot(r.raw.source,r.raw.work);Object.assign(kept,{raw:r.raw,rawBytes:bytes(r.raw),turn:a.turn,frame:a.frame,selected:a.selected,help:a.help,teachingPage:a.teachingPage,folds:{...a.folds},status:saved?.enabled===true&&saved?.ok===true?T.saved:saved?.enabled===false?T.session:T.uncertain});v.readonly.set(id,kept);v.screen='card';v.card=id;v.page=Math.floor(r.index/8);},'#rc-status');
 root.querySelectorAll('[data-rc-fold]').forEach(n=>n.addEventListener('toggle',()=>{if(live(n))(a?.folds||v.folds)[n.dataset.rcFold]=n.open;}));
